(function () {
"use strict";
function fetchJsonWithCandidates(relativePath) {
var rel = String(relativePath || "").replace(/^\.\//, "");
var urls = [];
function push(url) {
if (!url || urls.indexOf(url) >= 0) {
return;
}
urls.push(url);
}
push(rel);
push("./" + rel);
try {
var page = new URL(window.location.href);
var pageBase = String(page.pathname || "").replace(/[^/]*$/, "/");
push(pageBase + rel);
push(page.origin + pageBase + rel);
push(page.origin + "/" + rel);
if (/\/chronohaze(?:\/|$)/.test(page.pathname || "")) {
var repoBase = (page.pathname || "").replace(/^(.*?\/chronohaze)\/.*$/, "$1");
if (repoBase) {
push(repoBase + "/" + rel);
push(page.origin + repoBase + "/" + rel);
}
}
} catch (_e) {}
var i = 0;
function next() {
if (i >= urls.length) {
return Promise.reject(new Error("not found"));
}
var url = urls[i++];
return fetch(url, { cache: "no-cache" })
.then(function (res) {
if (!res.ok) {
throw new Error("HTTP " + res.status);
}
return res.json();
})
.catch(function () {
return next();
});
}
return next();
}
function buildProjectCard(project) {
var card = document.createElement("article");
card.className = "research-project-card";
function appendLine(label, value, extraClass) {
if (!value) return;
var p = document.createElement("p");
p.className = "research-project-line" + (extraClass ? " " + extraClass : "");
var strong = document.createElement("strong");
strong.textContent = label + ":";
var body = document.createElement("span");
body.className = "research-project-line-body";
body.textContent = value;
p.appendChild(strong);
p.appendChild(body);
card.appendChild(p);
}
if (project.kind) {
var kind = document.createElement("p");
kind.className = "research-project-kind";
kind.textContent = project.kind;
card.appendChild(kind);
}
if (project.title) {
var h3 = document.createElement("h3");
h3.textContent = project.title;
card.appendChild(h3);
}
if (project.problem) {
appendLine("Problem", project.problem);
}
if (project.method) {
appendLine("Method", project.method);
}
if (project.contribution) {
appendLine("Contribution", project.contribution);
}
if (project.status_label || project.status_detail || project.current_status || project.status) {
var statusLine = document.createElement("p");
statusLine.className = "research-project-line research-project-line--status";
var strong = document.createElement("strong");
strong.textContent = "Status:";
statusLine.appendChild(strong);
var wrap = document.createElement("span");
wrap.className = "research-project-status-wrap";
var statusLabel = project.status_label || project.status || "";
var statusDetail = project.status_detail || project.current_status || "";
if (statusLabel) {
var badge = document.createElement("span");
badge.className = "research-project-status-badge";
if (project.status_key) {
badge.className += " research-project-status-badge--" + String(project.status_key).replace(/_/g, "-");
}
badge.textContent = statusLabel;
wrap.appendChild(badge);
}
if (statusDetail) {
var detail = document.createElement("span");
detail.className = "research-project-status-detail";
detail.textContent = statusDetail;
wrap.appendChild(detail);
}
statusLine.appendChild(wrap);
card.appendChild(statusLine);
}
var links = Array.isArray(project.links) ? project.links : [];
if (links.length) {
var row = document.createElement("div");
row.className = "research-link-row";
links.forEach(function (link) {
if (!link || !link.href) {
return;
}
var a = document.createElement("a");
a.href = link.href;
a.textContent = link.label || link.href;
if (link.external) {
a.target = "_blank";
a.rel = "noopener noreferrer";
}
row.appendChild(a);
});
if (row.childNodes.length) {
card.appendChild(row);
}
}
return card;
}
function buildFastLink(item) {
var a = document.createElement("a");
a.className = "research-fast-link";
a.href = item.href || "#";
if (item.external) {
a.target = "_blank";
a.rel = "noopener noreferrer";
}
var kicker = document.createElement("span");
kicker.className = "research-fast-link-kicker";
kicker.textContent = item.kicker || "";
var strong = document.createElement("strong");
strong.textContent = item.title || "";
var desc = document.createElement("span");
desc.textContent = item.description || "";
a.appendChild(kicker);
a.appendChild(strong);
a.appendChild(desc);
return a;
}
function buildOutputCard(item) {
var a = document.createElement("a");
a.className = "research-output-card";
a.href = item.href || "#";
if (item.external) {
a.target = "_blank";
a.rel = "noopener noreferrer";
}
var kicker = document.createElement("span");
kicker.className = "research-output-kicker";
kicker.textContent = item.kicker || "";
var strong = document.createElement("strong");
strong.textContent = item.title || "";
var status = document.createElement("span");
status.className = "research-output-status";
var badge = document.createElement("span");
var statusKey = String(item.status_key || "").trim().replace(/_/g, "-");
badge.className = "research-output-status-badge" + (statusKey ? " research-output-status-badge--" + statusKey : "");
badge.textContent = item.status_label || item.status || "";
status.appendChild(badge);
if (item.status_detail) {
var detail = document.createElement("span");
detail.className = "research-output-status-detail";
detail.textContent = item.status_detail;
status.appendChild(detail);
}
var p = document.createElement("p");
p.textContent = item.description || "";
a.appendChild(kicker);
a.appendChild(strong);
a.appendChild(status);
a.appendChild(p);
return a;
}
function groupResearchOutputs(outputs, declaredGroups) {
var groups = [];
var byKey = Object.create(null);
var sourceGroups = Array.isArray(declaredGroups) ? declaredGroups : [];
sourceGroups.forEach(function (g) {
if (!g || !g.key) return;
var key = String(g.key);
var group = {
key: key,
title: g.title || key,
lead: g.lead || "",
items: []
};
groups.push(group);
byKey[key] = group;
});
(Array.isArray(outputs) ? outputs : []).forEach(function (item) {
if (!item) return;
var key = item.type || "other";
if (!byKey[key]) {
byKey[key] = { key: key, title: key, lead: "", items: [] };
groups.push(byKey[key]);
}
byKey[key].items.push(item);
});
return groups.filter(function (g) { return g.items && g.items.length; });
}
function buildResearchOutputGroup(group) {
var section = document.createElement("section");
section.className = "research-output-group";
section.setAttribute("data-output-group", group.key || "");
var head = document.createElement("div");
head.className = "research-output-group-head";
var h3 = document.createElement("h3");
h3.textContent = group.title || group.key || "Outputs";
head.appendChild(h3);
if (group.lead) {
var p = document.createElement("p");
p.textContent = group.lead;
head.appendChild(p);
}
section.appendChild(head);
var grid = document.createElement("div");
grid.className = "research-outputs-grid";
(group.items || []).forEach(function (item) {
grid.appendChild(buildOutputCard(item));
});
section.appendChild(grid);
return section;
}
function applyResearchCatalog(payload) {
if (!payload || typeof payload !== "object") {
return;
}
var hero = payload.hero || {};
var meta = payload.meta || {};
var interests = payload.interests || {};
var projects = Array.isArray(payload.projects) ? payload.projects : [];
var outputs = Array.isArray(payload.outputs) ? payload.outputs : [];
var outputGroups = Array.isArray(payload.output_groups) ? payload.output_groups : [];
var nowItems = Array.isArray(payload.now_items) ? payload.now_items : [];
var links = Array.isArray(payload.links) ? payload.links : [];
var projectsSection = payload.projects_section || {};
var outputsSection = payload.outputs_section || {};
var nowSection = payload.now_section || {};
var linksSection = payload.links_section || {};
var heroRoot = document.querySelector(".research-hero");
if (heroRoot) {
var eyebrow = heroRoot.querySelector(".research-eyebrow");
var h1 = heroRoot.querySelector(".research-hero-copy h1");
var subtitle = heroRoot.querySelector(".research-subtitle");
var positioning = heroRoot.querySelector(".research-positioning");
var chipRow = heroRoot.querySelector(".research-chip-row");
var metaRow = heroRoot.querySelector(".research-meta-row");
var lastUpdatedNode = heroRoot.querySelector(".research-last-updated");
var interestsTitle = heroRoot.querySelector(".research-hero-panel h2");
var interestsList = heroRoot.querySelector(".research-hero-panel ul");
if (eyebrow && hero.eyebrow) eyebrow.textContent = hero.eyebrow;
if (h1 && hero.name) h1.textContent = hero.name;
if (subtitle && hero.subtitle) subtitle.textContent = hero.subtitle;
if (positioning && hero.positioning) positioning.textContent = hero.positioning;
if (chipRow && Array.isArray(hero.chips) && hero.chips.length) {
chipRow.textContent = "";
hero.chips.forEach(function (chipText) {
var chip = document.createElement("span");
chip.className = "research-chip";
chip.textContent = chipText;
chipRow.appendChild(chip);
});
}
if (metaRow && meta && Array.isArray(meta.items) && meta.items.length) {
metaRow.textContent = "";
meta.items.forEach(function (entry) {
if (!entry || (!entry.label && !entry.value)) {
return;
}
var pill = document.createElement("span");
pill.className = "research-meta-pill";
var label = document.createElement("span");
label.className = "research-meta-label";
label.textContent = entry.label || "";
pill.appendChild(label);
if (entry.datetime) {
var time = document.createElement("time");
time.className = "research-last-updated";
time.dateTime = entry.datetime;
if (entry.timezone) {
time.setAttribute("data-timezone", entry.timezone);
time.title = entry.timezone;
}
time.textContent = entry.value || entry.datetime;
pill.appendChild(time);
} else {
var value = document.createElement("span");
value.textContent = entry.value || "";
pill.appendChild(value);
}
metaRow.appendChild(pill);
});
} else if (lastUpdatedNode && payload.generated_at) {
lastUpdatedNode.textContent = payload.generated_at;
lastUpdatedNode.dateTime = payload.generated_at;
}
if (interestsTitle && interests.title) {
interestsTitle.textContent = interests.title;
}
if (interestsList && Array.isArray(interests.items) && interests.items.length) {
interestsList.textContent = "";
interests.items.forEach(function (line) {
var li = document.createElement("li");
li.textContent = line;
interestsList.appendChild(li);
});
}
}
var projectsSectionRoot = document.querySelector(".research-projects-section");
if (projectsSectionRoot) {
var head = projectsSectionRoot.querySelector(".research-section-head");
if (head) {
var h2 = head.querySelector("h2");
var p = head.querySelector("p");
if (h2 && projectsSection.title) h2.textContent = projectsSection.title;
if (p && projectsSection.lead) p.textContent = projectsSection.lead;
}
var grid = projectsSectionRoot.querySelector(".research-project-grid");
if (grid && projects.length) {
grid.textContent = "";
projects.forEach(function (project) {
grid.appendChild(buildProjectCard(project));
});
}
}
var outputsSectionRoot = document.querySelector(".research-outputs-section");
if (outputsSectionRoot) {
var outputsHead = outputsSectionRoot.querySelector(".research-section-head");
if (outputsHead) {
var oh2 = outputsHead.querySelector("h2");
var op = outputsHead.querySelector("p");
if (oh2 && outputsSection.title) oh2.textContent = outputsSection.title;
if (op && outputsSection.lead) op.textContent = outputsSection.lead;
}
var outputsShell = outputsSectionRoot.querySelector(".research-outputs-shell, .research-outputs-grid");
if (outputsShell && outputs.length) {
outputsShell.textContent = "";
groupResearchOutputs(outputs, outputGroups).forEach(function (group) {
outputsShell.appendChild(buildResearchOutputGroup(group));
});
}
}
var nowSectionRoot = document.querySelector(".research-now-section");
if (nowSectionRoot) {
var nowHead = nowSectionRoot.querySelector(".research-section-head");
if (nowHead) {
var nh2 = nowHead.querySelector("h2");
var np = nowHead.querySelector("p");
if (nh2 && nowSection.title) nh2.textContent = nowSection.title;
if (np && nowSection.lead) np.textContent = nowSection.lead;
}
var nowList = nowSectionRoot.querySelector(".research-now-list");
if (nowList && nowItems.length) {
nowList.textContent = "";
nowItems.forEach(function (line) {
var li = document.createElement("li");
li.textContent = line;
nowList.appendChild(li);
});
}
}
var linksSectionRoot = document.querySelector(".research-fast-links-section");
if (linksSectionRoot) {
var head2 = linksSectionRoot.querySelector(".research-section-head");
if (head2) {
var h22 = head2.querySelector("h2");
var p2 = head2.querySelector("p");
if (h22 && linksSection.title) h22.textContent = linksSection.title;
if (p2 && linksSection.lead) p2.textContent = linksSection.lead;
}
var grid2 = linksSectionRoot.querySelector(".research-fast-links-grid");
if (grid2 && links.length) {
grid2.textContent = "";
links.forEach(function (item) {
grid2.appendChild(buildFastLink(item));
});
}
}
}
function bootResearchPage() {
if (!document.body || !document.body.classList.contains("research-landing-page")) {
return;
}
if (document.body.dataset.researchCatalogReady === "1") {
return;
}
document.body.dataset.researchCatalogReady = "1";
fetchJsonWithCandidates("assets/data/research-catalog.json")
.then(applyResearchCatalog)
.catch(function () {});
}
if (document.readyState === "loading") {
document.addEventListener("DOMContentLoaded", bootResearchPage, { once: true });
} else {
bootResearchPage();
}
})();
